'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=n=>`<svg aria-hidden="true"><use href="#${n}"/></svg>`;
function load(key,fallback){try{const v=localStorage.getItem(key);return v?JSON.parse(v):fallback}catch{return fallback}}
function save(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true}catch{toast('Storage unavailable. Your changes remain in this visit only.');return false}}
const validArray=(key,check)=>{const v=load(key,[]);return Array.isArray(v)?v.filter(check):[]};
const hasStrings=(o,keys)=>o&&typeof o==='object'&&keys.every(k=>typeof o[k]==='string');
const personas={worker:{name:'Jordan Diaz',initials:'JD',role:'Commercial janitor · Coastal district',verified:'Verified worker',holder:true},owner:{name:'Alex Morgan',initials:'AM',role:'Server owner · Union District',verified:'Verified owner',holder:true},visitor:{name:'Taylor Reed',initials:'TR',role:'Exploring the network',verified:null,holder:false}};
let personaKey='worker',activeTab='feed',jobFilter='all',jobQuery='',onlySaved=false,ledgerSample=false;
let posts=validArray('local6-v2-posts',p=>hasStrings(p,['id','name','initials','text','role','created']));
let customJobs=validArray('local6-v2-jobs',j=>hasStrings(j,['id','title','company','description','location','budget','category']));
let servers=validArray('local6-v2-servers',s=>hasStrings(s,['id','name','platform','description']));
let applications=validArray('local6-v2-applications',a=>hasStrings(a,['id','job','name','availability']));
const saved=new Set(validArray('local6-v2-saved',x=>typeof x==='string'));
const liked=new Set(validArray('local6-v2-liked',x=>typeof x==='string'));
const jobs=[
{id:'ocean',title:'Oceanfront hospitality janitor',company:'The Ocean Club',location:'Oceanfront district',budget:'Budget agreed before contract',category:'hospitality',holder:true,verified:true,shift:'Evening shift',description:'Maintain the lobby, pool deck, and guest areas. Document completed work and hand over to the morning crew.'},
{id:'neon',title:'Venue cleanup crew',company:'Neon Palms',location:'Entertainment district',budget:'Crew contract · Negotiable',category:'cleanup',holder:true,verified:true,shift:'Crew of 3',description:'Coordinate an after-event cleanup, clear communal areas, and submit completion evidence for approval.'},
{id:'marina',title:'Waterfront maintenance specialist',company:'Southside Marina',location:'South marina',budget:'Recurring contract · Negotiable',category:'maintenance',holder:false,verified:true,shift:'Recurring shifts',description:'Maintain dockside communal areas, follow the agreed shift schedule, and report maintenance needs to the operator.'}
];
const seedPosts=[
{id:'shift',name:'Jordan Diaz',initials:'JD',role:'Verified worker · Coastal district',holder:true,avatar:'',text:'Evening handover at the Ocean Club. Lobby, pool deck, and promenade completed. Building a work history should be as simple as showing the work.',image:true,foot:'Shift journal · Example post'},
{id:'hiring',name:'Neon Palms',initials:'NP',role:'Verified server owner · Entertainment district',holder:true,avatar:'purple',text:'Looking for a reliable crew for recurring venue cleanups. Clear scope, an agreed budget, and approval criteria before anyone starts. Details are on the jobs board.',job:true,foot:'Hiring update · Example post'},
{id:'notice',name:'Local 6 Union',initials:'06',role:'Community notice · Draft for ratification',holder:true,avatar:'mint',text:'Membership starts at 5,000,000 JANITOR. That gives you a seat at the proposed DAO. A verified-worker badge still needs trial shifts and approved work. Your wallet does not write your résumé.',notice:true,foot:'Workers’ agreement · Article 02'}
];
function badge(holder){return `<span class="badge ${holder?'holder':'visitor'}">${holder?'◆ Holder':'Non-holder'}</span>`}
function updateProfile(){const p=personas[personaKey];$('#profile-name').textContent=p.name;$('#profile-role').textContent=p.role;$('.profile-avatar').textContent=p.initials;$('#profile-badges').innerHTML=`${p.verified?`<span class="badge">✓ ${p.verified}</span>`:''}${badge(p.holder)}`;render()}
function setTab(tab,focus=false){if(!['feed','jobs','servers','treasury'].includes(tab))return;activeTab=tab;$$('[data-tab]').forEach(b=>{b.classList.toggle('selected',b.dataset.tab===tab);b.setAttribute('aria-pressed',b.dataset.tab===tab)});render();if(focus)$('#network').scrollIntoView({behavior:'smooth',block:'start'})}
function render(){if(activeTab==='feed')renderFeed();else if(activeTab==='jobs')renderJobsPage();else if(activeTab==='servers')renderServers();else renderLedger()}
function renderFeed(){const p=personas[personaKey];$('#network-content').innerHTML=`<div class="composer"><div class="compose-top"><span class="avatar">${p.initials}</span><button data-action="post">Share an update from work…</button></div><div class="composer-actions"><button data-action="post">${icon('people')} Work update</button><button data-action="job">${icon('brief')} Post a job</button><button data-action="register-server">${icon('pin')} List your server</button></div></div><div class="content-heading"><h3>From the workforce</h3><span>Community feed</span></div>${posts.map(post=>postCard({...post,local:true,holder:post.holder===true,avatar:'',foot:'Local draft · Not published'})).join('')}${seedPosts.map(postCard).join('')}`}
function postCard(p){return `<article class="feed-card ${p.local?'local-draft':''}"><div class="post-header"><span class="avatar ${p.avatar||''}">${esc(p.initials)}</span><div><h4>${esc(p.name)}${p.local?'':'<span class="check" aria-label="Sample verified profile">✓</span>'}</h4><p>${esc(p.role)}</p></div>${badge(p.holder)}</div><p class="post-copy">${esc(p.text).replace(/\n/g,'<br>')}</p>${p.image?'<div class="post-photo" role="img" aria-label="Illustrative coastal janitorial work"></div>':''}${p.job?'<div class="post-notice">Hiring a cleanup crew · <button class="text-button" data-show-job="neon">View example contract ↗</button></div>':''}${p.notice?'<div class="post-notice">5M+ tokens = membership. Verified work = reputation.</div>':''}<div class="post-footer"><span>${esc(p.foot)}</span>${p.local?`<button data-delete-post="${esc(p.id)}" class="delete-draft">Delete draft</button>`:`<button data-like="${esc(p.id)}" aria-pressed="${liked.has(p.id)}">${liked.has(p.id)?'♥ Appreciated':'♡ Appreciate'}</button>`}</div></article>`}
function allJobs(){return [...customJobs.map(j=>({...j,local:true,holder:j.holder===true,verified:false,shift:'Local draft'})),...jobs]}
function renderJobsPage(){
 $('#network-content').innerHTML=`<div class="content-heading"><h3>Job marketplace</h3><button class="button dark compact" data-action="job">Post a job +</button></div><p class="tab-description">Find a contract. Know who is hiring. See holder status alongside independent owner verification.</p><div class="search-row"><input type="search" id="job-search" value="${esc(jobQuery)}" placeholder="Search jobs, businesses, districts…" aria-label="Search job marketplace"><button id="saved-toggle" aria-pressed="${onlySaved}">Saved (${saved.size})</button></div><div class="filter-row" aria-label="Filter jobs">${[['all','All jobs'],['hospitality','Hospitality'],['cleanup','Cleanup'],['maintenance','Maintenance']].map(([id,label])=>`<button data-filter="${id}" aria-pressed="${jobFilter===id}" class="${jobFilter===id?'selected':''}">${label}</button>`).join('')}</div><div id="job-results"></div>`;renderJobResults();
 $('#job-search').addEventListener('input',e=>{jobQuery=e.target.value;renderJobResults()});
 $('#saved-toggle').addEventListener('click',()=>{onlySaved=!onlySaved;$('#saved-toggle').setAttribute('aria-pressed',onlySaved);renderJobResults()});
}
function renderJobResults(){const q=jobQuery.toLowerCase().trim();const filtered=allJobs().filter(j=>(jobFilter==='all'||j.category===jobFilter)&&(!onlySaved||saved.has(j.id))&&`${j.title} ${j.company} ${j.location}`.toLowerCase().includes(q));$('#job-results').innerHTML=filtered.length?filtered.map(j=>`<article class="job-card ${j.local?'local-draft':''}"><button class="save-job" data-save="${esc(j.id)}" aria-label="${saved.has(j.id)?'Unsave':'Save'} ${esc(j.title)}" aria-pressed="${saved.has(j.id)}">${saved.has(j.id)?'★':'☆'}</button><h4>${esc(j.title)}</h4><div class="job-company">${esc(j.company)}</div><div class="job-badges">${badge(j.holder)}<span class="badge ${j.verified?'':'pending'}">${j.verified?'✓ Verified owner':'Verification pending'}</span>${j.local?'<span class="badge sample">Your local draft</span>':''}</div><div class="job-meta"><span>${esc(j.location)}</span><span>${esc(j.shift)}</span></div><div class="job-bottom"><span>${esc(j.budget)}</span><button class="text-button" data-show-job="${esc(j.id)}">View contract ↗</button></div></article>`).join(''):'<div class="empty">No matching contracts.<br>Try a different search or filter.</div>'}
function renderServers(){ $('#network-content').innerHTML=`<div class="content-heading"><h3>Server directory</h3><button class="button dark compact" data-action="register-server">List your server +</button></div><p class="tab-description">Our flagship community and future partners. Server ownership, holder status, and listing approval are checked separately.</p>${servers.map(s=>`<article class="directory-card local-draft"><span class="badge pending">Unverified · Local draft</span><h4>${esc(s.name)}</h4><p>${esc(s.description)}</p><div class="job-meta">${esc(s.platform)}</div><div class="directory-actions"><span class="badge visitor">Holder status unverified</span><button class="text-button delete-draft" data-delete-server="${esc(s.id)}">Delete draft</button></div></article>`).join('')}<article class="directory-card"><div class="directory-cover" role="img" aria-label="Vice City-inspired union district illustration"></div><div class="directory-top"><span class="badge holder">LOCAL 6 FLAGSHIP</span><span class="badge pending">In development</span></div><h4>Vice City · Union District</h4><p>Our planned home for roleplay workers, crews, and local businesses. A professional hiring network with a district to build around it.</p><div class="job-meta"><span>Platform: to be confirmed</span><span>Join address: not available</span></div><div class="directory-actions"><a class="text-button" href="#server">Explore the district ↗</a><button class="text-button" data-action="server-interest">Draft application ↗</button></div></article><div class="modal-note">Directory preview. No live server availability or ownership verification is implied.</div>`}
const transactions=[{id:'reward',type:'Worker reward',amount:'−0.45 SOL',status:'Illustrative',description:'Example payment after approved shift evidence. No funds moved.'},{id:'fees',type:'Project fee allocation',amount:'+1.20 SOL',status:'Illustrative',description:'Example fee deposit into the union treasury. No transaction exists.'},{id:'hosting',type:'Server operations',amount:'−0.20 SOL',status:'Illustrative',description:'Example approved operating expense. No payment or vendor commitment exists.'}];
function renderLedger(){ $('#network-content').innerHTML=`<div class="content-heading"><h3>Union transactions</h3><span>Public ledger interface</span></div><p class="tab-description">Follow fees, worker rewards, and approved expenses from one place.</p><div class="ledger-stats"><div class="ledger-stat"><span>TREASURY BALANCE</span><strong>—</strong><small>No treasury address configured</small></div><div class="ledger-stat"><span>COLLECTED FEES TO UNION</span><strong>100%</strong><small>Proposed routing policy</small></div></div><label class="ledger-toggle"><input type="checkbox" id="sample-ledger" ${ledgerSample?'checked':''}> Preview illustrative transactions</label>${ledgerSample?`<div class="preview-notice">SIMULATED DATA · These rows are examples, not on-chain transactions.</div><div class="table-wrap"><table><thead><tr><th>ACTIVITY</th><th>AMOUNT</th><th>STATUS</th><th>DETAILS</th></tr></thead><tbody>${transactions.map(t=>`<tr><td>${t.type}</td><td>${t.amount}</td><td>${t.status}</td><td><button data-transaction="${t.id}">View ↗</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No live transactions to display.<br>The treasury address and fee routing will appear here once configured.</div>'}<p class="modal-note">A future live ledger should link every entry to its Solana transaction. This frontend has no wallet connection and does not send funds.</p>`;$('#sample-ledger').addEventListener('change',e=>{ledgerSample=e.target.checked;renderLedger()})}
const dialog=$('#dialog');let returnFocus;
function modal(content){if(!dialog.open)returnFocus=document.activeElement;$('#dialog-content').innerHTML=content;if(!dialog.open)dialog.showModal();document.body.classList.add('dialog-open');$('.dialog-close').focus()}
const heading=(k,t)=>`<div class="modal-kicker">${k}</div><h2 class="modal-title" id="dialog-title">${t}</h2>`;
$('.dialog-close').addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>{document.body.classList.remove('dialog-open');if(returnFocus?.isConnected)returnFocus.focus()});
dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
function guard(required){if((required==='worker'&&personaKey!=='worker')||(required==='owner'&&personaKey!=='owner')){const label=required==='worker'?'verified union worker':'verified server owner';modal(`${heading('ROLE REQUIREMENT',`This action needs a ${label}.`)}<p class="modal-body">The live product will verify wallet membership and work or server ownership. This preview lets you explore that experience with a labeled demo persona.</p><div class="modal-note">Switching preview personas does not verify a real person or grant live access.</div><button class="button dark" id="switch-persona">Explore ${required==='worker'?'worker':'owner'} preview ${icon('arrow')}</button>`);$('#switch-persona').onclick=()=>{personaKey=required;$('#persona').value=required;updateProfile();dialog.close();toast('Preview persona changed. Try the action again.')};return false}return true}
function formHandler(id,callback){$(id).addEventListener('submit',e=>{e.preventDefault();for(const input of e.currentTarget.querySelectorAll('input[required],textarea[required]')){if(input.type!=='checkbox'&&!input.value.trim()){input.setCustomValidity('Please enter a value.');input.reportValidity();input.addEventListener('input',()=>input.setCustomValidity(''),{once:true});return}}callback(new FormData(e.currentTarget))})}
function newID(){return crypto.randomUUID?.()||`${Date.now()}-${Math.random().toString(36).slice(2)}`}
function download(name,text,type='text/plain;charset=utf-8'){const url=URL.createObjectURL(new Blob([text],{type}));const link=document.createElement('a');link.href=url;link.download=name;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1500)}
function composePost(){if(!guard('worker'))return;modal(`${heading('WORKER JOURNAL','Post from work.')}<p class="modal-body">Share a shift handover, completed work, or an availability update with your network.</p><form id="post-form" class="modal-form"><label for="post-text">Your work update</label><textarea id="post-text" name="text" required maxlength="1500" placeholder="What did you work on today?"></textarea><div class="modal-note">Saves a local draft in this browser. It is not published to other users.</div><button class="button dark" type="submit">Save preview post ${icon('arrow')}</button></form>`);formHandler('#post-form',d=>{const p=personas[personaKey];posts.unshift({id:newID(),name:p.name,initials:p.initials,role:'Preview worker · Local draft',holder:p.holder,text:String(d.get('text')).trim(),created:new Date().toISOString()});save('local6-v2-posts',posts);setTab('feed');dialog.close();toast('Work update saved locally. Not published.')})}
function postJob(){if(!guard('owner'))return;modal(`${heading('SERVER OWNERS / HIRING','Post a job offering.')}<p class="modal-body">A clear scope and an agreed payment come before a shift.</p><form class="modal-form" id="job-form"><label for="job-title">Job title</label><input id="job-title" name="title" required maxlength="90" placeholder="e.g. Evening hospitality janitor"><label for="job-business">Business / server</label><input id="job-business" name="company" required maxlength="80"><label for="job-location">District / location</label><input id="job-location" name="location" required maxlength="100"><label for="job-category">Category</label><select id="job-category" name="category"><option value="hospitality">Hospitality</option><option value="cleanup">Cleanup</option><option value="maintenance">Maintenance</option></select><label for="job-budget">Payment, currency & terms</label><input id="job-budget" name="budget" required maxlength="120" placeholder="Specify amount and currency, or mark negotiable"><label for="job-scope">Scope and acceptance criteria</label><textarea id="job-scope" name="description" required maxlength="1500"></textarea><div class="modal-note">Local draft only. Real owner verification, moderation, and publishing need the backend.</div><button class="button dark" type="submit">Save job draft ${icon('arrow')}</button></form>`);formHandler('#job-form',d=>{customJobs.unshift({id:newID(),title:String(d.get('title')).trim(),company:String(d.get('company')).trim(),location:String(d.get('location')).trim(),budget:String(d.get('budget')).trim(),description:String(d.get('description')).trim(),category:String(d.get('category')),holder:personas[personaKey].holder});save('local6-v2-jobs',customJobs);jobQuery='';jobFilter='all';onlySaved=false;setTab('jobs');dialog.close();toast('Job draft saved locally. No public listing created.')})}
function showJob(id){const j=allJobs().find(x=>x.id===id);if(!j)return;modal(`${heading(j.local?'YOUR LOCAL DRAFT':'EXAMPLE CONTRACT',esc(j.title))}<div class="job-badges">${badge(j.holder)}<span class="badge ${j.verified?'':'pending'}">${j.verified?'Sample verified owner':'Verification pending'}</span></div><div class="modal-body"><p><strong>${esc(j.company)}</strong> · ${esc(j.location)}</p><p>${esc(j.description)}</p><p><strong>Payment:</strong> ${esc(j.budget)}</p><p>Before a live shift: agree scope, schedule, currency, payout deadline, evidence, and a dispute route.</p></div><div class="modal-note">Frontend ${j.local?'draft':'example'}. No employer booking, signed contract, or guaranteed payment.</div><div class="modal-actions"><button class="button dark" id="apply-job">Draft an application ${icon('arrow')}</button><button class="button glass" id="export-job">Download brief</button>${j.local?'<button class="text-button delete-draft" id="delete-job">Delete draft</button>':''}</div>`);$('#apply-job').onclick=()=>applyJob(j);$('#export-job').onclick=()=>download('local6-job-brief.txt',`LOCAL 6 — DRAFT CONTRACT\n\n${j.title}\nBusiness: ${j.company}\nLocation: ${j.location}\nPayment: ${j.budget}\n\n${j.description}\n\nAgree scope, evidence, approval, payment deadline, and disputes before work.\nFrontend draft only. No booking or employment agreement exists.\n`);if(j.local)$('#delete-job').onclick=()=>{customJobs=customJobs.filter(x=>x.id!==id);saved.delete(id);save('local6-v2-jobs',customJobs);save('local6-v2-saved',[...saved]);setTab('jobs');dialog.close();toast('Local job draft deleted.')};}
function applyJob(j){if(!guard('worker'))return;modal(`${heading('WORKER APPLICATION',esc(j.title))}<form class="modal-form" id="apply-form"><label for="applicant-name">Worker name</label><input id="applicant-name" name="name" required maxlength="70" value="${esc(personas[personaKey].name)}"><label for="availability">Availability and relevant experience</label><textarea id="availability" name="availability" required maxlength="1500"></textarea><div class="modal-note">This application stays in your browser and downloads as a draft. It is not sent to an employer.</div><button class="button dark" type="submit">Save & download application ${icon('arrow')}</button></form>`);formHandler('#apply-form',d=>{const a={id:newID(),job:j.title,name:String(d.get('name')).trim(),availability:String(d.get('availability')).trim()};applications.push(a);save('local6-v2-applications',applications);download('local6-worker-application.txt',`LOCAL 6 — DRAFT APPLICATION\nJob: ${a.job}\nName: ${a.name}\n\n${a.availability}\n\nNot submitted. No membership or worker verification performed.\n`);dialog.close();toast('Application saved and downloaded. Not submitted.')})}
function registerServer(){modal(`${heading('SERVER DIRECTORY','Register your server.')}<p class="modal-body">Draft a listing for review. Server verification will require ownership evidence; holding tokens alone does not verify an operator.</p><form class="modal-form" id="server-form"><label for="server-name">Server name</label><input id="server-name" name="name" required maxlength="80"><label for="server-platform">Platform / current status</label><input id="server-platform" name="platform" required maxlength="100" placeholder="e.g. GTA V RP · In development"><label for="server-about">Community and hiring needs</label><textarea id="server-about" name="description" required maxlength="1500"></textarea><label class="inline-label"><input type="checkbox" required>I understand this is an unverified local draft.</label><button type="submit" class="button dark">Save server listing ${icon('arrow')}</button></form>`);formHandler('#server-form',d=>{servers.unshift({id:newID(),name:String(d.get('name')).trim(),platform:String(d.get('platform')).trim(),description:String(d.get('description')).trim()});save('local6-v2-servers',servers);setTab('servers');dialog.close();toast('Server listing saved locally. Verification pending.')})}
function serverInterest(){modal(`${heading('VICE CITY / UNION DISTRICT','Your place in the city.')}<p class="modal-body">Plan how you want to participate in the Local 6 server project.</p><form class="modal-form" id="interest-form"><label for="interest-name">Name / handle</label><input id="interest-name" name="name" required maxlength="70"><label for="interest-role">I want to join as</label><select id="interest-role" name="role"><option>Janitor</option><option>Crew lead</option><option>Business operator</option><option>Server contributor</option></select><label for="interest-plan">What would you bring?</label><textarea id="interest-plan" name="plan" required maxlength="1500"></textarea><div class="modal-note">Downloads a draft application. No server slot, whitelist, or submitted application is created.</div><button class="button dark" type="submit">Download application ${icon('arrow')}</button></form>`);formHandler('#interest-form',d=>{download('local6-server-application.txt',`LOCAL 6 — SERVER APPLICATION DRAFT\n\nName: ${d.get('name')}\nRole: ${d.get('role')}\n\n${d.get('plan')}\n\nNot submitted. Server in development; no access or whitelist slot granted.\n`);toast('Server application downloaded. Not submitted.')})}
function membership(){modal(`${heading('LOCAL 6 / MEMBERSHIP','5 million tokens. One union.')}<p class="modal-body">The proposed entry requirement is <strong>at least 5,000,000 $JANITOR</strong> in a verified wallet. DAO membership gives eligible holders a voice in union priorities, budgets, and rules.</p><div class="modal-note">This frontend cannot check balances. The official mint, wallet verification, snapshot policy, and DAO are not connected. Worker and owner verification remain separate.</div><form class="modal-form" id="membership-form"><label for="member-name">Name on your preview card</label><input id="member-name" name="name" required maxlength="28" placeholder="Your name / handle"><label class="inline-label"><input type="checkbox" required>I understand this is a provisional card, not verified membership.</label><button type="submit" class="button dark">Create preview card ${icon('arrow')}</button></form><p class="modal-body"><a href="agreement.html#membership">Read Article 02: Membership →</a></p>`);formHandler('#membership-form',d=>{const name=String(d.get('name')).trim();save('local6-v2-card',{name});modal(`${heading('PROVISIONAL / NOT VERIFIED','Your union card.')}<div class="download-card"><small>GTA 6 JANITOR / LOCAL 6</small><h3>${esc(name)}</h3><p>Membership threshold · 5,000,000 JANITOR</p><small>PREVIEW CARD · NO VERIFIED MEMBERSHIP</small></div><button class="button dark" id="download-card">Download card ${icon('arrow')}</button>`);$('#download-card').onclick=()=>download('local6-union-card.svg',`<svg xmlns="http://www.w3.org/2000/svg" width="900" height="540"><defs><linearGradient id="b"><stop stop-color="#35213e"/><stop offset="1" stop-color="#945b80"/></linearGradient></defs><rect width="900" height="540" rx="30" fill="url(#b)"/><rect x="24" y="24" width="852" height="492" rx="20" fill="none" stroke="#d6a0c3"/><g font-family="Arial,sans-serif"><text x="65" y="100" fill="#efbed7" font-size="22" letter-spacing="4">GTA 6 JANITOR / LOCAL 6</text><text x="65" y="245" fill="white" font-size="${name.length>18?36:50}" font-weight="700">${esc(name)}</text><text x="65" y="305" fill="#edcfdf" font-size="24">Membership threshold: 5,000,000 JANITOR</text><text x="65" y="440" fill="#efbed7" font-size="17">PROVISIONAL PREVIEW · NOT VERIFIED MEMBERSHIP</text><text x="65" y="475" fill="#d7b1cd" font-size="12">Independent fan community. No wallet checked. No DAO or server access granted.</text></g></svg>`,'image/svg+xml')})}
function economics(){modal(`${heading('THE $100K AMBITION','Put a budget behind the headline.')}<p class="modal-body">$100,000 a year is a campaign ambition, not an available salary. This calculator shows the funding a program would need before making that offer.</p><form class="modal-form"><label for="worker-count">Number of workers</label><input id="worker-count" type="number" min="1" max="10000" value="10" step="1"><label for="reward-share">Share of union revenue available for wages / rewards (%)</label><input id="reward-share" type="number" min="1" max="100" value="70" step="1"></form><div class="economics-grid"><div><span>ANNUAL WORKER BUDGET</span><strong id="annual-budget"></strong></div><div><span>REQUIRED MONTHLY REVENUE</span><strong id="monthly-revenue"></strong></div></div><div class="modal-note">Hypothetical USD budgeting only. The 70% input is an example, not an adopted allocation. Excludes taxes, fees, volatility, and implementation costs. No funded salary, live treasury revenue, or payouts are established.</div>`);const update=()=>{const n=Number($('#worker-count').value),share=Number($('#reward-share').value);const valid=Number.isInteger(n)&&n>=1&&n<=10000&&Number.isInteger(share)&&share>=1&&share<=100;const usd=v=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(v);$('#annual-budget').textContent=valid?usd(n*100000):'—';$('#monthly-revenue').textContent=valid?usd(n*100000/12/(share/100)):'—'};$('#worker-count').oninput=update;$('#reward-share').oninput=update;update()}
const clipInfo={adin:{name:'Adin Ross',id:'2060234010781954189',url:'https://x.com/AdinUpdate/status/2060234010781954189',report:'https://gta6bible.com/streamers-think-that-gta-6-could-turn-in-game-jobs-into/',context:'The reported janitor comment concerns his proposed server, not Local 6 or $JANITOR. The source was found through published reporting; original X playback depends on availability.'},banks:{name:'FaZe Banks & Adin Ross',id:'1886588181128339611',url:'https://x.com/vvsrak/status/1886588181128339611',report:'https://decrypt.co/304597/adin-ross-faze-banks-crypto-gta-6-server',context:'A discussion of their proposed GTA server economy. This is not an endorsement of Local 6 or a promise of a $100K janitor salary.'}};
let twitterReady;
function loadTwitter(){if(window.twttr?.widgets)return Promise.resolve(window.twttr);if(twitterReady)return twitterReady;twitterReady=new Promise((resolve,reject)=>{const s=document.createElement('script');s.src='https://platform.twitter.com/widgets.js';s.async=true;const timer=setTimeout(()=>reject(new Error('Video provider unavailable')),9000);s.onload=()=>{clearTimeout(timer);window.twttr?.ready?window.twttr.ready(t=>resolve(t)):reject(new Error('Video provider unavailable'))};s.onerror=()=>{clearTimeout(timer);reject(new Error('Video provider unavailable'))};document.head.append(s)});return twitterReady}
async function showClip(key){const c=clipInfo[key];if(!c)return;modal(`${heading('ORIGINAL FOOTAGE / SOURCE LINK',c.name)}<p class="modal-body">${c.context}</p><div class="clip-embed" id="clip-embed">Loading the original X post…</div><div class="source-links"><a href="${c.url}" target="_blank" rel="noopener noreferrer">Open original clip ↗</a><a href="${c.report}" target="_blank" rel="noopener noreferrer">Read source reporting ↗</a></div><p class="modal-note">The artwork on the page is AI-illustrated. This player loads the source post, not a synthetic voice or fabricated statement.</p>`);const container=$('#clip-embed');try{const tw=await loadTwitter();if(!container.isConnected)return;container.textContent='';const result=await Promise.race([tw.widgets.createTweet(c.id,container,{theme:'light',dnt:true,align:'center'}),new Promise((_,reject)=>setTimeout(()=>reject(new Error('timeout')),10000))]);if(!result&&container.isConnected)container.textContent='The embedded clip is unavailable. Use the original-source link below.'}catch{if(container.isConnected)container.textContent='The embedded clip could not load. Open the original-source link below.'}}
