const actions={post:composePost,job:postJob,'register-server':registerServer,'server-interest':serverInterest,membership,economics,status};
document.addEventListener('click',e=>{const action=e.target.closest('[data-action]');if(action&&actions[action.dataset.action])return actions[action.dataset.action]();const tab=e.target.closest('[data-tab]');if(tab)return setTab(tab.dataset.tab);const filter=e.target.closest('[data-filter]');if(filter){jobFilter=filter.dataset.filter;$$('[data-filter]').forEach(b=>{b.classList.toggle('selected',b===filter);b.setAttribute('aria-pressed',b===filter)});return renderJobResults()}const saveButton=e.target.closest('[data-save]');if(saveButton){const id=saveButton.dataset.save;saved.has(id)?saved.delete(id):saved.add(id);save('local6-v2-saved',[...saved]);renderJobResults();$('#saved-toggle').textContent=`Saved (${saved.size})`;const replacement=$(`[data-save="${CSS.escape(id)}"]`);if(replacement)replacement.focus();return}const job=e.target.closest('[data-show-job]');if(job)return showJob(job.dataset.showJob);const like=e.target.closest('[data-like]');if(like){const id=like.dataset.like;liked.has(id)?liked.delete(id):liked.add(id);save('local6-v2-liked',[...liked]);like.setAttribute('aria-pressed',liked.has(id));like.textContent=liked.has(id)?'♥ Appreciated':'♡ Appreciate';return}const delPost=e.target.closest('[data-delete-post]');if(delPost){posts=posts.filter(p=>p.id!==delPost.dataset.deletePost);save('local6-v2-posts',posts);renderFeed();return}const delServer=e.target.closest('[data-delete-server]');if(delServer){servers=servers.filter(s=>s.id!==delServer.dataset.deleteServer);save('local6-v2-servers',servers);renderServers();return}const transaction=e.target.closest('[data-transaction]');if(transaction){const t=transactions.find(t=>t.id===transaction.dataset.transaction);return modal(`${heading('ILLUSTRATIVE TRANSACTION',t.type)}<p class="modal-body"><b>${t.amount}</b></p><p class="modal-body">${t.description}</p><div class="modal-note">No transaction signature or explorer link exists for this example. Live records require a configured treasury and chain data.</div>`)}const clip=e.target.closest('[data-clip]');if(clip)return showClip(clip.dataset.clip)});
